public class ArrayOperationsSuite {
    public static int findMax(int[] arr) {
        int max = arr[0];
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] > max) {
                max = arr[i];
            }
        }
        return max;
    }

    public static double calculateAverage(int[] arr) {
        if (arr.length == 0) return 0.0;
        int sum = 0;
        for (int val : arr) {
            sum += val;
        }
        return (double) sum / arr.length;
    }

    public static int linearSearch(int[] arr, int target) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == target) {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] scores = {75, 88, 94, 62, 85};

        System.out.println("Max Score: " + findMax(scores));
        System.out.println("Class Average: " + calculateAverage(scores));
        System.out.println("Search 94 Index: " + linearSearch(scores, 94));
        System.out.println("Search 100 Index: " + linearSearch(scores, 100));
    }
}

