public class Main {
    public static int findMin(int[] arr) {
        int min = arr[0];
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] < min) {
                min = arr[i];
            }
        }
        return min;
    }

    public static void main(String[] args) {
        int[] data = {42, 17, 89, 5, 23};
        System.out.println("Minimum: " + findMin(data));
    }
}

