practiceProblems.solutionCode:
public class Main {
    public static int indexOf(int[] arr, int target) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == target) {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] data = {15, 30, 45, 60};
        System.out.println("Found 45 at: " + indexOf(data, 45));
        System.out.println("Found 99 at: " + indexOf(data, 99));
    }
}

