public class Main {
    public static int countOccurrences(int[] arr, int target) {
        int count = 0;
        for (int x : arr) {
            if (x == target) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        int[] numbers = {4, 7, 4, 2, 4, 8};
        System.out.println("Occurrences of 4: " + countOccurrences(numbers, 4));
    }
}

