practiceProblems.solutionCode:
public class Main {
    public static int calculateRangeSpread(int[] arr) {
        int min = arr[0];
        int max = arr[0];
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] < min) min = arr[i];
            if (arr[i] > max) max = arr[i];
        }
        return max - min;
    }

    public static void main(String[] args) {
        int[] values = {12, 48, 5, 92, 33};
        System.out.println("Range Spread: " + calculateRangeSpread(values));
    }
}
